/**
 * The shape the feature files (tests/features) keep, so the test catalog can
 * name every scenario and the targets can run it.
 *
 * Read with @cucumber/gherkin, the parser playwright-bdd uses. gherkin-lint
 * would check most of this, but it depends on gherkin 9, whose protobufjs has
 * high advisories, so the rules live here:
 *
 *   - a file holds a Feature (`empty-file`) with at least one scenario
 *     (`no-scenarios`), and parses (`parse-error`)
 *   - every scenario has exactly one `@id:<kebab-case>` tag (`scenario-id`);
 *     tags of the Feature and the Rule count as the scenario's own
 *   - every scenario names its subject with `@endpoint:`, `@function:` or
 *     `@scenario:` (`scenario-subject`), and a target, `@hono`, `@nextjs` or
 *     `@http` (`scenario-target`): a scenario of no target is generated by no
 *     project and would never run
 *   - no two scenarios have the same name (`duplicate-scenario-name`) and no
 *     two the same id (`duplicate-id`), in any file
 *   - a Scenario Outline uses every column of its Examples in its name or
 *     steps, and every `<variable>` it uses is a column (`unused-variable`)
 *
 * Usage: node .github/scripts/lint-features.mjs (pnpm run lint)
 */
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const require = createRequire(new URL('../../tests/steps/package.json', import.meta.url));
const { AstBuilder, GherkinClassicTokenMatcher, Parser } = require('@cucumber/gherkin');
const { IdGenerator } = require('@cucumber/messages');
const REPOSITORY_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');

/** The directory of the feature files. */
export const FEATURES_ROOT = 'tests/features';

const SUBJECT_PREFIXES = ['@endpoint:', '@function:', '@scenario:'];
const TARGET_TAGS = new Set(['@hono', '@nextjs', '@http']);
const ID_TAG = /^@id:(.*)$/;
const KEBAB_CASE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const VARIABLE = /<([^<>]+)>/g;

/**
 * The parsed document of a feature file.
 *
 * @throws {Error} the errors of the parser, when the file is not Gherkin
 */
function parse(source) {
  const parser = new Parser(new AstBuilder(IdGenerator.incrementing()), new GherkinClassicTokenMatcher());
  return parser.parse(source);
}

/** The scenarios of a feature with the tags of their Feature and Rule. */
function scenariosOf(feature) {
  return feature.children.flatMap((child) => {
    if (child.scenario) return [{ scenario: child.scenario, inherited: feature.tags }];
    if (child.rule) {
      return child.rule.children
        .filter((ruleChild) => ruleChild.scenario)
        .map((ruleChild) => ({ scenario: ruleChild.scenario, inherited: [...feature.tags, ...child.rule.tags] }));
    }
    return [];
  });
}

/** The `<variables>` of a text. */
function variablesOf(text) {
  return [...text.matchAll(VARIABLE)].map((match) => match[1]);
}

/** The texts of a scenario where a variable of its Examples may be used: its name and its steps, their tables and doc strings. */
function usageTexts(scenario) {
  return [
    scenario.name,
    ...scenario.steps.flatMap((step) => [
      step.text,
      ...(step.dataTable?.rows.flatMap((row) => row.cells.map((cell) => cell.value)) ?? []),
      ...(step.docString ? [step.docString.content] : []),
    ]),
  ];
}

/** The unused-variable violations of a Scenario Outline. */
function variableViolations(path, scenario) {
  if (scenario.examples.length === 0) return [];
  const used = new Set(usageTexts(scenario).flatMap(variablesOf));
  const violations = [];
  const columns = new Set();
  for (const examples of scenario.examples) {
    for (const cell of examples.tableHeader?.cells ?? []) {
      columns.add(cell.value);
      if (!used.has(cell.value)) {
        violations.push({
          path,
          line: cell.location.line,
          rule: 'unused-variable',
          message: `The column "${cell.value}" of the Examples of "${scenario.name}" is used nowhere in the name or the steps`,
        });
      }
    }
  }
  for (const variable of used) {
    if (!columns.has(variable)) {
      violations.push({
        path,
        line: scenario.location.line,
        rule: 'unused-variable',
        message: `"${scenario.name}" uses <${variable}>, which no column of its Examples defines`,
      });
    }
  }
  return violations;
}

/** The violations of one scenario, and the id it declares. */
function scenarioViolations(path, scenario, inherited) {
  const violations = [];
  const report = (rule, message) => violations.push({ path, line: scenario.location.line, rule, message });
  const tags = [...inherited, ...scenario.tags].map((tag) => tag.name);
  const ids = [...new Set(tags.flatMap((tag) => ID_TAG.exec(tag)?.[1] ?? []))];
  if (ids.length === 0) {
    report('scenario-id', `"${scenario.name}" has no @id:<kebab-case-id> tag`);
  } else if (ids.length > 1) {
    report('scenario-id', `"${scenario.name}" has more than one id: ${ids.map((id) => `@id:${id}`).join(' ')}`);
  } else if (!KEBAB_CASE.test(ids[0])) {
    report('scenario-id', `The id of "${scenario.name}" is not kebab-case: @id:${ids[0]}`);
  }
  if (!tags.some((tag) => SUBJECT_PREFIXES.some((prefix) => tag.startsWith(prefix) && tag.length > prefix.length))) {
    report('scenario-subject', `"${scenario.name}" names no subject: tag it, or its Feature, with ${SUBJECT_PREFIXES.map((prefix) => `${prefix}<name>`).join(', ')}`);
  }
  const examplesTags = scenario.examples.map((examples) => examples.tags.map((tag) => tag.name));
  const targeted = tags.some((tag) => TARGET_TAGS.has(tag))
    || (examplesTags.length > 0 && examplesTags.every((names) => names.some((tag) => TARGET_TAGS.has(tag))));
  if (!targeted) {
    report('scenario-target', `"${scenario.name}" runs on no target: tag it with ${[...TARGET_TAGS].join(', ')}`);
  }
  violations.push(...variableViolations(path, scenario));
  return { violations, id: ids.length === 1 ? ids[0] : undefined };
}

/** The violations of feature files, the names and ids compared across all of them. */
export function lintFeatures(sources) {
  const violations = [];
  const names = new Map();
  const ids = new Map();
  for (const { path, source } of sources) {
    let document;
    try {
      document = parse(source);
    } catch (error) {
      const errors = error.errors ?? [error];
      for (const each of errors) {
        violations.push({ path, line: each.location?.line ?? 1, rule: 'parse-error', message: each.message });
      }
      continue;
    }
    const { feature } = document;
    if (!feature) {
      violations.push({ path, line: 1, rule: 'empty-file', message: 'The file has no Feature' });
      continue;
    }
    const scenarios = scenariosOf(feature);
    if (scenarios.length === 0) {
      violations.push({ path, line: feature.location.line, rule: 'no-scenarios', message: `The feature "${feature.name}" has no scenario` });
    }
    for (const { scenario, inherited } of scenarios) {
      const { violations: found, id } = scenarioViolations(path, scenario, inherited);
      violations.push(...found);
      const at = `${path}:${scenario.location.line}`;
      const sameName = names.get(scenario.name);
      if (sameName) {
        violations.push({ path, line: scenario.location.line, rule: 'duplicate-scenario-name', message: `"${scenario.name}" is also the name of the scenario at ${sameName}` });
      } else {
        names.set(scenario.name, at);
      }
      if (id === undefined) continue;
      const sameId = ids.get(id);
      if (sameId) {
        violations.push({ path, line: scenario.location.line, rule: 'duplicate-id', message: `@id:${id} is also the id of the scenario at ${sameId}` });
      } else {
        ids.set(id, at);
      }
    }
  }
  return violations;
}

/** The feature files of a directory in a stable order. */
function featureFiles(directory) {
  return readdirSync(directory).sort().flatMap((entry) => {
    const path = join(directory, entry);
    if (statSync(path).isDirectory()) return featureFiles(path);
    return entry.endsWith('.feature') ? [path] : [];
  });
}

/** The violations of the feature files of the repository. */
export function lintRepository(repositoryRoot) {
  const directory = join(repositoryRoot, FEATURES_ROOT);
  if (!existsSync(directory)) return [];
  return lintFeatures(featureFiles(directory).map((file) => ({
    path: `${FEATURES_ROOT}/${relative(directory, file).split('\\').join('/')}`,
    source: readFileSync(file, 'utf8'),
  })));
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const violations = lintRepository(REPOSITORY_ROOT);
  for (const violation of violations) {
    console.error(`${violation.path}:${violation.line}: ${violation.rule}: ${violation.message}`);
  }
  if (violations.length > 0) {
    console.error(`\n${violations.length} feature file violation(s).`);
    process.exitCode = 1;
  } else {
    console.log('Feature files verified.');
  }
}
